<section class="workspace-avatar-editor" data-avatar-editor aria-label="Ảnh đại diện">
  <h3 data-w-vi="Ảnh đại diện" data-w-en="Profile photo">Ảnh đại diện</h3>
  <div class="wa-controls"><label class="wa-pick"><span data-w-vi="Chọn ảnh" data-w-en="Choose photo">Chọn ảnh</span><input type="file" data-avatar-input accept="image/jpeg,image/png,image/webp" aria-label="Chọn ảnh đại diện"></label><button type="button" data-avatar-save hidden data-w-vi="Lưu ảnh" data-w-en="Save photo">Lưu ảnh</button><button type="button" data-avatar-cancel hidden data-w-vi="Hủy" data-w-en="Cancel">Hủy</button><button type="button" data-avatar-remove hidden data-w-vi="Xóa ảnh" data-w-en="Remove photo">Xóa ảnh</button></div>
  <img class="wa-preview" data-avatar-preview hidden alt="Ảnh đại diện xem trước">
  <p class="wa-hint" data-w-vi="JPEG, PNG hoặc WebP, tối đa 5 MiB. Ảnh được cắt vuông trước khi lưu." data-w-en="JPEG, PNG or WebP, up to 5 MiB. Photos are cropped square before saving.">JPEG, PNG hoặc WebP, tối đa 5 MiB. Ảnh được cắt vuông trước khi lưu.</p>
  <p data-avatar-status role="status"></p>
</section>
